<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Teacher','Admin']); check_csrf(); if($_SERVER['REQUEST_METHOD']==='POST'){$sid=(int)$_POST['student_id'];$sub=(int)$_POST['subject_id'];$pre=(float)$_POST['prelim'];$mid=(float)$_POST['midterm'];$fin=(float)$_POST['final'];$avg=($pre+$mid+$fin)/3;$gpa=grade_to_gpa($avg);$remarks=$avg>=75?'Passed':'Failed';db()->prepare('INSERT INTO grades(student_id,subject_id,prelim,midterm,final,gpa,remarks,encoded_by) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(student_id,subject_id) DO UPDATE SET prelim=excluded.prelim,midterm=excluded.midterm,final=excluded.final,gpa=excluded.gpa,remarks=excluded.remarks,encoded_by=excluded.encoded_by')->execute([$sid,$sub,$pre,$mid,$fin,$gpa,$remarks,$_SESSION['user_id']]); generate_prediction($sid,false); set_flash('success','Grade saved.'); redirect('grades.php');} render_header('Encode Grades'); ?><div class="page-title"><div><h1>Encode Grades</h1><p>Teacher grade management.</p></div></div><div class="row g-4"><div class="col-lg-4"><div class="panel"><div class="panel-title">Grade Form</div><form method="post"><?= csrf_field() ?><div class="mb-3"><label>Student</label><select name="student_id" class="form-select"><?php foreach(rows('SELECT s.id,s.student_no,u.full_name FROM students s JOIN users u ON u.id=s.user_id') as $s): ?><option value="<?= e($s['id']) ?>"><?= e($s['student_no'].' - '.$s['full_name']) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label>Subject</label><select name="subject_id" class="form-select"><?php foreach(rows('SELECT * FROM subjects') as $s): ?><option value="<?= e($s['id']) ?>"><?= e($s['code'].' - '.$s['title']) ?></option><?php endforeach; ?></select></div><div class="row"><div class="col"><label>Prelim</label><input type="number" step=".01" name="prelim" class="form-control" required></div><div class="col"><label>Midterm</label><input type="number" step=".01" name="midterm" class="form-control" required></div><div class="col"><label>Final</label><input type="number" step=".01" name="final" class="form-control" required></div></div><button class="btn btn-primary w-100 mt-3">Save Grade</button></form></div></div><div class="col-lg-8"><div class="panel"><div class="panel-title">Encoded Grades</div><table class="table"><thead><tr><th>Student</th><th>Subject</th><th>Prelim</th><th>Midterm</th><th>Final</th><th>GPA</th><th>Remarks</th></tr></thead><tbody><?php foreach(rows('SELECT g.*,u.full_name,sub.code FROM grades g JOIN students s ON s.id=g.student_id JOIN users u ON u.id=s.user_id JOIN subjects sub ON sub.id=g.subject_id ORDER BY g.created_at DESC') as $g): ?><tr><td><?= e($g['full_name']) ?></td><td><?= e($g['code']) ?></td><td><?= e($g['prelim']) ?></td><td><?= e($g['midterm']) ?></td><td><?= e($g['final']) ?></td><td><?= e($g['gpa']) ?></td><td><?= e($g['remarks']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php render_footer(); ?>
